import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    groups = [[] for _ in range(n)]
    for i in range(2, len(data), 3):
        l, r, x = data[i:i + 3]
        if l == r:
            print(0)
            return
        groups[l - 1].append((x - 1, r))

    # dp[l][r] is the valid count on [l,r), divided by (r-l)!.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = 1

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # For each possible maximum position, the smallest right endpoint
    # of a forbidden interval whose left endpoint is at least l.
    limits = [n + 1] * n
    for l in range(n - 1, -1, -1):
        for x, r in groups[l]:
            if r < limits[x]:
                limits[x] = r
        row = dp[l]
        for r in range(l + 1, n + 1):
            total = 0
            for k in range(l, r):
                if r < limits[k]:
                    total += row[k] * dp[k + 1][r]
            row[r] = total % MOD * inv[r - l] % MOD

    answer = dp[0][n]
    for i in range(2, n + 1):
        answer = answer * i % MOD
    print(answer)


if __name__ == '__main__':
    main()

