    for v in a:
        deg[v] += 1

    q = deque(i for i in range(n) if deg[i] == 0)
    dp = [None] * n
    while q:
        v = q.popleft()
        p = a[v]
        cur = dp[v]
        dst = dp[p]
        if cur is None:
            if dst is None:
                dp[p] = array('I', range(1, m + 1))
            else:
                for j in range(m):
                    dst[j] = dst[j] * (j + 1) % MOD
        else:
            s = 0
            if dst is None:
                for j in range(m):
                    s = (s + cur[j]) % MOD
                    cur[j] = s
                dp[p] = cur
            else:
                for j in range(m):
                    s = (s + cur[j]) % MOD
                    dst[j] = dst[j] * s % MOD
            dp[v] = None
        deg[p] -= 1
        if deg[p] == 0:
            q.append(p)

    ans = 1
    for i in range(n):
        if not deg[i]:
            continue
        prod = None
        v = i
        while deg[v]:
            deg[v] = 0
            cur = dp[v]
            if cur is not None:
                if prod is None:
                    prod = cur
                else:
                    for j in range(m):
                        prod[j] = prod[j] * cur[j] % MOD
            v = a[v]
        ways = m if prod is None else sum(prod) % MOD
        ans = ans * ways % MOD
    print(ans)


if __name__ == '__main__':
    main()

