import sys

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for i, x in enumerate(data[1:]):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = e
            p += 1
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (n - 1)
            factors[x][i] = 1

    answer = 1
    for p, exponents in factors.items():
        total = sum(exponents)
        powers = [1] * (total + 1)
        for j in range(total):
            powers[j + 1] = powers[j] * p % MOD

        # Normalize each prefix so that its minimum exponent is zero.
        # dp[h] is its total weight with final exponent h.
        dp = [1]
        for i, e in enumerate(exponents, 1):
            if e == 0:
                dp = [v * powers[h] % MOD for h, v in enumerate(dp)]
                continue

            length = len(dp) + e
            padded = [0] * e + dp + [0] * (2 * e)
            ndp = [
                (padded[h] + padded[h + 2 * e]) * powers[h] % MOD
                for h in range(length)
            ]

            # A downward step below zero raises all i previous exponents.
            base = pow(p, i, MOD)
            weight = 1
            extra = 0
            for h in range(e - 1, -1, -1):
                weight = weight * base % MOD
                if h < len(dp):
                    extra += dp[h] * weight
            ndp[0] = (ndp[0] + extra) % MOD
            dp = ndp

        answer = answer * sum(dp) % MOD

    print(answer)


if __name__ == '__main__':
    solve()

