                remaining = m - i - 1
                subtotal = 0
                for count in good:
                    j = count - prefix
                    if j < 0:
                        continue
                    if j > remaining:
                        break
                    subtotal += inv[j] * inv[remaining - j] % MOD
                answer = (answer + fact[remaining] * subtotal) % MOD
                prefix += 1
