import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    rows = [0] * n
    for k in range(m):
        u, v = data[2 + 2 * k] - 1, data[3 + 2 * k] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form over GF(2).
    pivots = []
    rank = 0
    for col in range(n):
        bit = 1 << col
        found = next((i for i in range(rank, n) if rows[i] & bit), -1)
        if found == -1:
            continue
        rows[rank], rows[found] = rows[found], rows[rank]
        for i in range(n):
            if i != rank and rows[i] & bit:
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    # Place each nullspace basis vector in its own bit position.
    pivot_set = set(pivots)
    answer = [0] * n
    index = 0
    for col in range(n):
        if col in pivot_set:
            continue
        value = 1 << index
        index += 1
        answer[col] = value
        for i, p in enumerate(pivots):
            if rows[i] & (1 << col):
                answer[p] |= value

    if any(x == 0 for x in answer):
        print('No')
    else:
        print('Yes')
        print(*answer)


