    pivot_set = set(pivots)
    answer = [0] * n
    index = 0
    for col in range(n):
        if col in pivot_set:
            continue
        value = 1 << index
        index += 1
        answer[col] = value
        for i, p in enumerate(pivots):
            if rows[i] & (1 << col):
                answer[p] |= value

