from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        w = m + 2
        size = (n + 2) * w
        a = [3] * size
        for r, row in enumerate(grid, 1):
            a[r*w+1:r*w+m+1] = row

        ans = 0
        for dr, dc in ((1, 1), (1, -1), (-1, -1), (-1, 1)):
            # A clockwise turn changes (dr, dc) into (dc, -dr).
            cr, cc = dc, -dr
            step = cr*w + cc
            tail = [0] * size
            rows = range(n, 0, -1) if cr == 1 else range(1, n+1)
            for r in rows:
                for i in range(r*w+1, r*w+m+1):
                    v = a[i]
                    expected = 2 if v == 1 else 2-v
                    tail[i] = 1 + tail[i+step] if a[i+step] == expected else 1

            prefix = [0] * size
            step = dr*w + dc
            rows = range(1, n+1) if dr == 1 else range(n, 0, -1)
            for r in rows:
                for i in range(r*w+1, r*w+m+1):
                    v = a[i]
                    if v == 1:
                        p = 1
                    else:
                        j = i-step
                        prev = a[j]
                        if prefix[j] and v == (2 if prev == 1 else 2-prev):
                            p = prefix[j]+1
                        else:
                            continue
                    prefix[i] = p
                    length = p + tail[i]-1
                    if length > ans:
                        ans = length
        return ans

