from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        remaining = list(range(1, n + 1))
        odd, even = (n + 1) // 2, n // 2
        answer = []

        while remaining:
            for i, value in enumerate(remaining):
                parity = value % 2
                if answer:
                    if parity == answer[-1] % 2:
                        continue
                elif n % 2 and parity == 0:
                    continue

                o = odd - parity
                e = even - (1 - parity)
                count = fact[o] * fact[e]
                if k > count:
                    k -= count
                else:
                    answer.append(value)
                    remaining.pop(i)
                    odd, even = o, e
                    break
            else:
                return []

        return answer

