class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        m = (n + 1) // 2
        weights = [
            (powers[i] + powers[n - 1 - i]) % k
            if i != n - 1 - i else powers[i]
            for i in range(m)
        ]

        # dp[i] contains all remainders attainable by positions i..m-1.
        full = (1 << k) - 1
        shifts = [set(d * w % k for d in range(10)) for w in range(k)]
        dp = [0] * (m + 1)
        dp[m] = 1
        for i in range(m - 1, -1, -1):
            mask = dp[i + 1]
            if mask == full:
                dp[i] = full
            else:
                result = 0
                for shift in shifts[weights[i]]:
                    result |= ((mask << shift) | (mask >> (k - shift))) & full
                dp[i] = result

        left = []
        remainder = 0
        for i, w in enumerate(weights):
            for digit in range(9, 0 if i == 0 else -1, -1):
                r = (remainder + digit * w) % k
                if dp[i + 1] & (1 << ((-r) % k)):
                    left.append(str(digit))
