class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1

        answer = len(s)
        for target in range(1, max(counts) + 1):
            absent = present = 0
            previous = 0
            for count in counts:
                new_absent = min(absent, present) + count
                deficit = max(target - count, 0)
                new_present = abs(count - target) + min(
                    absent - min(previous, deficit),
                    present - min(max(previous - target, 0), deficit)
                )
                absent, present = new_absent, new_present
                previous = count
            answer = min(answer, absent, present)
        return answer

