class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        order = [0]
        for u in order:
            for v, w in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        # free: parent edge absent; used: parent edge present.
        free = [0] * n
        used = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if v == parent[u]:
                    continue
                base += free[v]
                gain = w + used[v] - free[v]
                if gain > 0:
                    gains.append(gain)
            gains.sort(reverse=True)
            best = base + sum(gains[:k])
            free[u] = best
            used[u] = best - (gains[k - 1] if len(gains) >= k else 0)

        return free[0]

