import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    for k in range(2, len(data), 3):
        x, y, z = data[k] - 1, data[k + 1] - 1, data[k + 2]
        graph[x].append((y, z))
        graph[y].append((x, z))
    del data

    values = [-1] * n
    for root in range(n):
        if values[root] != -1:
            continue
        values[root] = 0
        component = [root]
        top = 0
        for v in component:
            for w, z in graph[v]:
                target = values[v] ^ z
                if values[w] == -1:
                    values[w] = target
                    top |= target
                    component.append(w)
                elif values[w] != target:
                    print(-1)
                    return

        size = len(component)
        # With at most two vertices, the root-zero assignment is optimal.
        if size <= 2:
            continue
        mask = 0
        for bit in range(top.bit_length()):
            count = sum((values[v] >> bit) & 1 for v in component)
            if count * 2 > size:
                mask |= 1 << bit
        if mask:
            for v in component:
                values[v] ^= mask

    print(' '.join(map(str, values)))


