class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)
        start = [0] * n
        end = [0] * n
        order = []
        stack = [0]
        while stack:
            u = stack.pop()
            if u >= 0:
                start[u] = len(order)
                stack.append(~u)
                stack.extend(reversed(children[u]))
            else:
                u = ~u
                order.append(s[u])
                end[u] = len(order)
        text = '#' + '#'.join(order) + '#'
        m = len(text)
        radius = [0] * m
        center = right = 0
        for i in range(m):
            if i < right:
                radius[i] = min(right - i, radius[2 * center - i])
            r = radius[i]
            while i - r - 1 >= 0 and i + r + 1 < m and text[i-r-1] == text[i+r+1]:
                r += 1
            radius[i] = r
            if i + r > right:
                center = i
                right = i + r
        return [radius[start[u] + end[u]] >= end[u] - start[u] for u in range(n)]

