from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        minimum = [10**30] * k
        minimum[0] = 0
        prefix = 0
        answer = -10**30

        for i, value in enumerate(nums, 1):
            prefix += value
            remainder = i % k
            candidate = prefix - minimum[remainder]
            if candidate > answer:
                answer = candidate
            if prefix < minimum[remainder]:
                minimum[remainder] = prefix

        return answer

