class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        # Bit s represents whether a subset of the processed values sums to s.
        reachable = [1 if x else 0 for x in nums]
        remaining = sum(x > 0 for x in nums)
        if remaining == 0:
            return 0

        targets = [1 << x for x in nums]
        masks = [(1 << (x + 1)) - 1 for x in nums]

        for k, (left, right, value) in enumerate(queries, 1):
