import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        graph = [[] for _ in range(n)]
        for a, b, w in edges:
            graph[b].append((a, w))
        inf = 10**9
        dist = [inf] * n
        dist[0] = 0
        heap = [(0, 0)]
        remaining = n
        while heap:
            cost, u = heapq.heappop(heap)
            if cost != dist[u]:
                continue
            remaining -= 1
            if remaining == 0:
                return cost
            for v, w in graph[u]:
                candidate = max(cost, w)
                if candidate < dist[v]:
                    dist[v] = candidate
                    heapq.heappush(heap, (candidate, v))
        return -1

from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        a = b = c = d = e = f = 0
        for i in range(n // 2):
            x, y, z = cost[i]
            u, v, w = cost[n - 1 - i]
            a, b, c, d, e, f = (
                x + v + min(c, d, e),
                x + w + min(c, e, f),
                y + u + min(a, b, f),
                y + w + min(a, e, f),
                z + u + min(a, b, d),
                z + v + min(b, c, d),
            )
        return min(a, b, c, d, e, f)

